"use client"

import * as React from "react"
import { toast } from "sonner"

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { TooltipProvider } from "@/components/ui/tooltip"
import { CloneVoiceFlow } from "@/components/mockups/voice-cloning/clone-voice-flow"
import { PersonaVoice } from "@/components/mockups/voice-cloning/persona-voice"
import { VoiceLibrary } from "@/components/mockups/voice-cloning/voice-library"
import { AppShell } from "@/components/shell/app-shell"
import { MockupShell } from "@/components/shell/mockup-shell"
import {
  OUTCOMES,
  PERSONA,
  type SampleOutcome,
  type Viewer,
  type Voice,
  voicesFor,
} from "@/lib/mockups/voice-cloning-data"

const SURFACES = [
  { id: "library", label: "Voice library" },
  { id: "persona", label: "Persona" },
] as const

type Surface = (typeof SURFACES)[number]["id"]

const VIEWERS: { id: Viewer; label: string }[] = [
  { id: "client", label: "Client org" },
  { id: "sarj", label: "Super admin" },
]

export default function VoiceCloningPage() {
  const [surface, setSurface] = React.useState<Surface>("persona")
  const [viewer, setViewer] = React.useState<Viewer>("client")
  const [outcome, setOutcome] = React.useState<SampleOutcome>("clean")
  const [voices, setVoices] = React.useState<Record<Viewer, Voice[]>>(() => ({
    client: voicesFor("client"),
    sarj: voicesFor("sarj"),
  }))
  const [voiceId, setVoiceId] = React.useState(PERSONA.voiceId)
  const [cloning, setCloning] = React.useState(false)

  const looking: Viewer = surface === "library" ? "sarj" : viewer

  const changeViewer = (next: Viewer) => {
    setViewer(next)
    setVoiceId(PERSONA.voiceId)
  }

  const deleted = (voice: Voice) => {
    setVoices((current) => ({
      ...current,
      [looking]: current[looking].filter((entry) => entry.id !== voice.id),
    }))
    if (voice.id === voiceId) setVoiceId(PERSONA.voiceId)
  }

  const created = (voice: Voice) => {
    setVoices((current) => ({
      ...current,
      [looking]: [voice, ...current[looking]],
    }))
    if (surface === "persona") {
      if (
        voice.language === PERSONA.language &&
        voice.gender === PERSONA.gender
      ) {
        setVoiceId(voice.id)
      }
      return
    }
    toast(
      voice.status === "pending"
        ? `${voice.name} created. Publishing is pending approval.`
        : `${voice.name} created`,
    )
  }

  return (
    <MockupShell
      actions={
        <>
          <Select
            onValueChange={(value) => setOutcome(value as SampleOutcome)}
            value={outcome}
          >
            <SelectTrigger aria-label="Sample outcome" size="sm">
              <SelectValue />
            </SelectTrigger>
            <SelectContent align="end" position="popper">
              {OUTCOMES.map((entry) => (
                <SelectItem key={entry.id} value={entry.id}>
                  {entry.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <ToggleGroup
            aria-label="Viewer"
            disabled={surface === "library"}
            onValueChange={(next) => {
              if (next) changeViewer(next as Viewer)
            }}
            size="sm"
            type="single"
            value={looking}
            variant="outline"
          >
            {VIEWERS.map((entry) => (
              <ToggleGroupItem key={entry.id} value={entry.id}>
                {entry.label}
              </ToggleGroupItem>
            ))}
          </ToggleGroup>
          <ToggleGroup
            aria-label="Surface"
            onValueChange={(next) => {
              if (next) setSurface(next as Surface)
            }}
            size="sm"
            type="single"
            value={surface}
            variant="outline"
          >
            {SURFACES.map((entry) => (
              <ToggleGroupItem key={entry.id} value={entry.id}>
                {entry.label}
              </ToggleGroupItem>
            ))}
          </ToggleGroup>
        </>
      }
      title="Voice cloning on the platform"
    >
      <TooltipProvider>
        {surface === "library" ? (
          <AppShell active="Voice Library">
            <VoiceLibrary
              onClone={() => setCloning(true)}
              onDelete={deleted}
              voices={voices.sarj}
            />
          </AppShell>
        ) : (
          <AppShell
            active="Personas"
            breadcrumb={["Personas", PERSONA.name]}
            hiddenItems={viewer === "client" ? ["Voice Library"] : undefined}
          >
            <PersonaVoice
              onClone={() => setCloning(true)}
              onDelete={deleted}
              onVoiceChange={setVoiceId}
              voiceId={voiceId}
              voices={voices[viewer]}
            />
          </AppShell>
        )}

        {/* Keyed so switching surface or viewer opens a fresh flow. */}
        <CloneVoiceFlow
          canPublish={looking === "sarj"}
          defaults={{ language: PERSONA.language, gender: PERSONA.gender }}
          key={`${surface}-${looking}`}
          onCreated={created}
          onOpenChange={setCloning}
          open={cloning}
          outcome={outcome}
        />
      </TooltipProvider>
    </MockupShell>
  )
}

"use client"

import { Badge } from "@/components/ui/badge"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { LANGUAGE_NAMES } from "@/lib/design-system/data"

/** Must not wrap: a second line grows the row past the table's fixed 40px. */
export function LanguageChip({ languages }: { languages: string[] }) {
  return (
    <span className="flex flex-nowrap items-center gap-1 whitespace-nowrap">
      {languages.map((code) => (
        <Tooltip key={code}>
          <TooltipTrigger asChild>
            <Badge
              className="bg-muted text-muted-foreground"
              variant="secondary"
            >
              <span aria-label={LANGUAGE_NAMES[code]}>{code}</span>
            </Badge>
          </TooltipTrigger>
          <TooltipContent>{LANGUAGE_NAMES[code]}</TooltipContent>
        </Tooltip>
      ))}
    </span>
  )
}

export function NotApplicable() {
  return <span className="text-muted-foreground">—</span>
}

"use client"

import * as React from "react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { Dialog as DialogPrimitive } from "radix-ui"

import { CloseIcon, StepBackIcon } from "@/components/design-system/icons"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

/** power3.out, the motion scale's ease-out-cubic. */
const EASE = [0.215, 0.61, 0.355, 1] as const

const DOT = {
  rest: 0.15,
  enter: 0.5,
  radius: 9999,
  spring: { type: "spring", visualDuration: 0.35, bounce: 0 },
} as const

type CreationFlowProps = {
  title: string
  question: string
  /** Changes when the screen does; drives the slide between screens. */
  stepKey: string
  step: number
  steps: number
  /** 1 going forward, -1 going back: which way the screens slide. */
  direction: number
  /** Null hides Back. */
  onBack: (() => void) | null
  onClose: () => void
  children: React.ReactNode
}

export function CreationFlow({
  framed = false,
  open = true,
  ...props
}: CreationFlowProps & {
  framed?: boolean
  open?: boolean
}) {
  if (framed) {
    return (
      /* translate-x-0 makes this box the containing block for anything fixed inside it. */
      <div className="relative flex h-180 translate-x-0 flex-col overflow-hidden rounded-xl border bg-background">
        <FlowBody {...props} />
      </div>
    )
  }

  return (
    <DialogPrimitive.Root
      onOpenChange={(next) => (next ? undefined : props.onClose())}
      open={open}
    >
      <DialogPrimitive.Portal>
        <DialogPrimitive.Content className="fixed inset-0 z-modal flex flex-col bg-background duration-200 ease-out-cubic outline-none data-open:animate-in data-open:fade-in-0 data-closed:animate-out data-closed:fade-out-0 motion-reduce:animate-none">
          <DialogPrimitive.Title className="sr-only">
            {props.title}
          </DialogPrimitive.Title>
          <DialogPrimitive.Description className="sr-only">
            {props.question}
          </DialogPrimitive.Description>
          <FlowBody {...props} />
        </DialogPrimitive.Content>
      </DialogPrimitive.Portal>
    </DialogPrimitive.Root>
  )
}

function FlowBody({
  title,
  question,
  stepKey,
  step,
  steps,
  direction,
  onBack,
  onClose,
  children,
}: CreationFlowProps) {
  const reduced = useReducedMotion() ?? false

  return (
    <>
      <div className="flex h-16 shrink-0 items-center justify-between px-5">
        {onBack ? (
          <Button onClick={onBack} size="sm" variant="ghost">
            <StepBackIcon />
            Back
          </Button>
        ) : (
          <span />
        )}
        <Button
          aria-label="Close"
          onClick={onClose}
          size="icon"
          variant="outline"
        >
          <CloseIcon />
        </Button>
      </div>

      {/* min-h-full centres the column while it is short and scrolls from the top once it is taller, instead of clipping. */}
      <div className="min-h-0 flex-1 overflow-y-auto">
        <div className="mx-auto flex min-h-full w-full max-w-2xl flex-col justify-center gap-8 px-6 py-12">
          <AnimatePresence custom={direction} initial={false} mode="wait">
            <motion.div
              animate={{ opacity: 1, x: 0 }}
              className="flex flex-col gap-8"
              custom={direction}
              exit="exit"
              initial="enter"
              key={stepKey}
              transition={{ duration: reduced ? 0 : 0.2, ease: EASE }}
              variants={{
                enter: (d: number) => ({
                  opacity: 0,
                  x: reduced ? 0 : d * 24,
                }),
                exit: (d: number) => ({
                  opacity: 0,
                  x: reduced ? 0 : d * -24,
                }),
              }}
            >
              <header className="flex flex-col gap-1">
                <h2 className="text-2xl font-semibold tracking-tight">
                  {title}
                </h2>
                <p className="text-base text-muted-foreground">{question}</p>
              </header>
              {children}
            </motion.div>
          </AnimatePresence>
        </div>
      </div>

      <StepDots step={step} steps={steps} />
    </>
  )
}

function StepDots({ step, steps }: { step: number; steps: number }) {
  const reduced = useReducedMotion() ?? false

  return (
    <div className="flex h-14 shrink-0 items-center justify-center">
      <span className="sr-only">
        Step {step + 1} of {steps}
      </span>
      {/* popLayout removes a leaving dot at once, so the others close the gap on the same spring. */}
      <div aria-hidden className="relative flex items-center gap-1.5">
        <AnimatePresence initial={false} mode="popLayout">
          {Array.from({ length: steps }, (_, i) => (
            <motion.span
              animate={{ opacity: i === step ? 1 : DOT.rest, scale: 1 }}
              className={cn(
                "h-1.5 bg-foreground",
                i === step ? "w-6" : "w-1.5",
              )}
              exit={{ opacity: 0, scale: DOT.enter }}
              initial={{ opacity: 0, scale: DOT.enter }}
              /* Keyed by position so a path that changes length only adds or drops the tail. */
              key={i}
              layout
              /* Radius in style, not rounded-full, so motion can counter-scale it; a class radius squashes mid-stretch. */
              style={{ borderRadius: DOT.radius }}
              transition={reduced ? { duration: 0 } : DOT.spring}
            />
          ))}
        </AnimatePresence>
      </div>
    </div>
  )
}

"use client"

import * as React from "react"

import { FieldHint } from "@/components/design-system/field-hint"
import { FieldError, FieldLabel } from "@/components/ui/field"

export function FieldHeader({
  children,
  htmlFor,
  hint,
  error,
}: {
  children: React.ReactNode
  htmlFor: string
  hint?: string
  error?: string | null
}) {
  return (
    <div className="flex items-baseline justify-between gap-3">
      {hint ? (
        <FieldHint hint={hint} htmlFor={htmlFor}>
          {children}
        </FieldHint>
      ) : (
        <FieldLabel htmlFor={htmlFor}>{children}</FieldLabel>
      )}
      {error ? (
        <FieldError className="text-end" id={errorId(htmlFor)}>
          {error}
        </FieldError>
      ) : null}
    </div>
  )
}

export function errorId(htmlFor: string) {
  return `${htmlFor}-error`
}

"use client"

import * as React from "react"

import { HintIcon } from "@/components/design-system/icons"
import { FieldLabel } from "@/components/ui/field"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

export function FieldHint({
  children,
  className,
  hint,
  htmlFor,
}: {
  children: React.ReactNode
  /** Placement only: a horizontal `Field` needs to be told to grow this wrapper. */
  className?: string
  hint: string
  htmlFor: string
}) {
  return (
    <div className={cn("flex items-center gap-1.5", className)}>
      {/* FieldLabel, not Label, so a hinted field keeps the same line height as its neighbours. */}
      <FieldLabel htmlFor={htmlFor}>{children}</FieldLabel>
      <Tooltip>
        {/* Sized here because TooltipTrigger does not size its icon, and HugeIcons falls through to 24px. */}
        <TooltipTrigger
          aria-label={`About ${children?.toString().toLowerCase()}`}
          className="rounded-full text-muted-foreground/70 transition-colors duration-150 ease-out-cubic outline-none hover:text-foreground focus-visible:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50 motion-reduce:transition-none"
          type="button"
        >
          <HintIcon className="size-3.5" />
        </TooltipTrigger>
        <TooltipContent
          align="start"
          className="text-balance"
          side="top"
          sideOffset={4}
        >
          {hint}
        </TooltipContent>
      </Tooltip>
    </div>
  )
}

